function media(parent,name,x,y,targetW,targetH){
  const comp=getComp(name);
  if(!comp){ console.log("MISSING "+name); return null; }
  const inst=comp.createInstance();
  inst.x=x; inst.y=y; inst.name=name;
  parent.appendChild(inst);
  // try to set size
  try{ inst.resize(targetW||inst.width, targetH||inst.height);}catch(err){}
