function hexc(h){ const n=parseInt(h.slice(1),16); return {r:((n>>16)&255)/255, g:((n>>8)&255)/255, b:(n&255)/255}; }
function solid(h){ return {type:"SOLID", color:hexc(h)}; }

function makeText(s, size, weight, color, w){
