function recolorIcon(iconNode, colorHex){
  // walk nested vectors and recolor fills that are dark (not white)
  function setFill(node){
    if(node.type==="VECTOR"||node.type==="FRAME"||node.type==="GROUP"){
      if(node.fills&&Array.isArray(node.fills)){
        const nonWhite = node.fills.filter(f=>f.type==="SOLID" && !(f.color.r>0.9&&f.color.g>0.9&&f.color.b>0.9));
        if(nonWhite.length){
          node.fills=nonWhite.map(f=>({type:"SOLID", color:hexc(colorHex)}));
        }
      }
      if(node.strokes&&Array.isArray(node.strokes)){
        const nonWhite = node.strokes.filter(f=>f.type==="SOLID" && !(f.color.r>0.9&&f.color.g>0.9&&f.color.b>0.9));
        if(nonWhite.length){ node.strokes=nonWhite.map(f=>({type:"SOLID", color:hexc(colorHex)})); }
      }
    }
    if(node.children){ node.children.forEach(ch=>setFill(ch)); }
  }
  setFill(iconNode);
}

